package deezer.patches

// Native libraries keep their original build IDs across these app versions.
// Each payload restores changed byte ranges only; no complete library is bundled.
internal data class NativeStartupRestore(
    val path: String, val inputHash: String, val outputHash: String, val outputSize: Int, val delta: String,
)

internal fun nativeStartupRestores(): List<NativeStartupRestore> = listOf(
    nativeStartupRestore0(),
    nativeStartupRestore1(),
    nativeStartupRestore2(),
    nativeStartupRestore3(),
    nativeStartupRestore4(),
    nativeStartupRestore5(),
    nativeStartupRestore6(),
    nativeStartupRestore7(),
    nativeStartupRestore8(),
)

